//! Turns long target predicates into short, readable `cfg` aliases.
//!
//! Keeping these definitions in one place means the rest of the crate can use
//! names such as `platform_windows` instead of repeating
//! `#[cfg(all(target_os = "windows", ...))]` on every item.

use cfg_aliases::cfg_aliases;

fn main() {
    cfg_aliases! {
        // Operating-system aliases.
        platform_windows: { target_os = "windows" },
        platform_linux:   { target_os = "linux" },
        platform_apple:   { any(
            target_os = "macos",
            target_os = "ios",
            target_os = "tvos",
            target_os = "watchos",
        ) },
        platform_bsd:     { any(
            target_os = "freebsd",
            target_os = "openbsd",
            target_os = "netbsd",
            target_os = "dragonfly",
        ) },

        // Target-family alias. `wasm` spans several `target_os` values
        // (`unknown`, `wasi`, ...), so it is described by family instead.
        platform_wasm: { target_family = "wasm" },

        // Architecture alias.
        pointer_64: { target_pointer_width = "64" },
    }
}

//! Compile-time platform selection.
//!
//! [`build.rs`] rewrites target predicates into short aliases
//! (`platform_windows`, `platform_apple`, ...). This module compiles exactly
//! one implementation and re-exports it as [`imp`], so the rest of the crate
//! only ever talks to `platform::imp` with no `#[cfg]` noise.

#[cfg(unix)]
mod unix_common;

cfg_if::cfg_if! {
    if #[cfg(platform_windows)] {
        mod windows;
        pub(crate) use self::windows as imp;
    } else if #[cfg(platform_apple)] {
        mod apple;
        pub(crate) use self::apple as imp;
    } else if #[cfg(platform_linux)] {
        mod linux;
        pub(crate) use self::linux as imp;
    } else if #[cfg(platform_bsd)] {
        mod bsd;
        pub(crate) use self::bsd as imp;
    } else if #[cfg(platform_wasm)] {
        mod wasm;
        pub(crate) use self::wasm as imp;
    } else {
        mod unsupported;
        pub(crate) use self::unsupported as imp;
    }
}

