//! Turns long target predicates into short, readable `cfg` aliases.

use std::env;

fn main() {
    // Register every alias so the compiler knows they are expected (avoids
    // `unexpected_cfgs` warnings on recent toolchains).
    for alias in [
        "platform_windows",
        "platform_linux",
        "platform_apple",
        "platform_bsd",
        "platform_wasm",
        "pointer_64",
    ] {
        println!("cargo:rustc-check-cfg=cfg({alias})");
    }

    let os = env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    let family = env::var("CARGO_CFG_TARGET_FAMILY").unwrap_or_default();
    let arch = env::var("CARGO_CFG_TARGET_POINTER_WIDTH").unwrap_or_default();

    let mut enable = |alias: &str, on: bool| {
        if on {
            println!("cargo:rustc-cfg={alias}");
        }
    };

    enable("platform_windows", os == "windows");
    enable("platform_linux", os == "linux");
    enable(
        "platform_apple",
        matches!(os.as_str(), "macos" | "ios" | "tvos" | "watchos"),
    );
    enable(
        "platform_bsd",
        matches!(os.as_str(), "freebsd" | "openbsd" | "netbsd" | "dragonfly"),
    );
    enable("platform_wasm", family == "wasm");
    enable("pointer_64", arch == "64");

    println!("cargo:rerun-if-changed=build.rs");
}
```

